CREATE TYPE project_status AS ENUM ('NEW','ACTIVE','ON_HOLD','COMPLETED','CANCELLED');
CREATE TYPE job_status AS ENUM ('NEW','ASSIGNED','IN_PROGRESS','IN_REVIEW','REVISION','READY_FOR_APPROVAL','APPROVED','COMPLETED','CANCELLED');
CREATE TYPE priority_level AS ENUM ('LOW','NORMAL','HIGH','URGENT');
CREATE TABLE projects (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), project_code VARCHAR(30) UNIQUE NOT NULL, client_id UUID NOT NULL REFERENCES clients(id), name VARCHAR(180) NOT NULL, description TEXT, priority priority_level NOT NULL DEFAULT 'NORMAL', status project_status NOT NULL DEFAULT 'NEW', deadline DATE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE designers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID UNIQUE REFERENCES users(id), name VARCHAR(120) NOT NULL, email VARCHAR(254), phone VARCHAR(30), status record_status NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE design_jobs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), job_code VARCHAR(30) UNIQUE NOT NULL, project_id UUID NOT NULL REFERENCES projects(id), title VARCHAR(180) NOT NULL, design_type VARCHAR(100) NOT NULL, lead_designer_id UUID REFERENCES designers(id), priority priority_level NOT NULL DEFAULT 'NORMAL', status job_status NOT NULL DEFAULT 'NEW', base_charge NUMERIC(12,2) NOT NULL DEFAULT 0, deadline DATE, notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE revisions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), design_job_id UUID NOT NULL REFERENCES design_jobs(id), version_no INTEGER NOT NULL, feedback TEXT NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'REQUESTED', requested_by VARCHAR(120), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(design_job_id,version_no));
CREATE TABLE proofs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), design_job_id UUID NOT NULL REFERENCES design_jobs(id), version_no INTEGER NOT NULL, file_path TEXT, status VARCHAR(30) NOT NULL DEFAULT 'DRAFT', client_feedback TEXT, submitted_at TIMESTAMPTZ, approved_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE payments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), project_id UUID NOT NULL REFERENCES projects(id), amount NUMERIC(12,2) NOT NULL CHECK(amount>=0), payment_type VARCHAR(30) NOT NULL DEFAULT 'CLIENT', status VARCHAR(30) NOT NULL DEFAULT 'PENDING', reference VARCHAR(100), paid_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX projects_client_idx ON projects(client_id,status);CREATE INDEX jobs_project_idx ON design_jobs(project_id,status);CREATE INDEX jobs_designer_idx ON design_jobs(lead_designer_id,status);CREATE INDEX revisions_job_idx ON revisions(design_job_id,version_no DESC);CREATE INDEX proofs_job_idx ON proofs(design_job_id,version_no DESC);CREATE INDEX payments_project_idx ON payments(project_id,status);
